public int[] classify(int[] nums) {
    int pos = 0, neg = 0, zero = 0;
    for (int x : nums) {
        if (x > 0) pos++;
        else if (x < 0) neg++;
        else zero++;
    }
    return new int[]{pos, neg, zero};
}

code.python:
def classify(nums: list[int]) -> list[int]:
    pos = neg = zero = 0
    for x in nums:
        if x > 0:
            pos += 1
        elif x < 0:
            neg += 1
        else:
            zero += 1
    return [pos, neg, zero]
